const stored = (value) => ({ type: "bnode", value, "rdf4j:reference": true });
const iri = (value) => ({ type: "uri", value });

test("certified stored blank-node IDs encode once and round-trip arbitrary raw identifiers", () => {
  for (const [raw, token] of [
    ["alice", "<_:alice>"], ["", "<_:>"], ["_:alice", "<_:_:alice>"],
    ["a b>\\u0041", "<_:a\\u0020b\\u003E\\u005Cu0041>"],
    ['\t\n\r"{}|^`', '<_:\\u0009\\u000A\\u000D\\u0022\\u007B\\u007D\\u007C\\u005E\\u0060>'],
    ["a🙂日本", "<_:a🙂日本>"],
  ]) {
    const id = sparqlNodeId(stored(raw));
    assert.equal(id, token, JSON.stringify(raw));
    assert.equal(sparqlFacetValueToken(id), token);
    assert.deepEqual(sparqlTermFromNodeId(id), stored(raw));
    assert.notEqual(id, sparqlNodeId({ type: "bnode", value: raw }));
  }
});

test("uncertified and query-local blank labels never become reusable operands", () => {
  for (const id of ["_:alice", "__rdf_bnode__:alice", sparqlNodeId({type:"bnode",value:"alice"})]) {
    assert.equal(sparqlFacetValueToken(id), null);
  }
  for (const malformed of ["<_:x\\q>", "<_:x\\uZZZZ>", "<_:x\\U00110000>", "<_:x y>", "<_:x> trailing"]) {
    assert.equal(sparqlTermFromNodeId(malformed), undefined, malformed);
  }
});

test("bound resource queries and blank named scopes share canonical resource operands", () => {
  assert.match(expandQuery(["<_:alice>", "urn:iri"], 80, "<_:\\u0067raph>"), /VALUES \?selected \{ <_:alice> \}/);
  assert.match(scoped("?s ?p ?o .", "<_:graph>"), /GRAPH <_:graph>/);
  assert.match(labelQuery(["<_:alice>"], [], "all"), /VALUES \?resource \{ <_:alice> \}/);
});

test("loaded blank endpoints are excluded from both directions of subsequent pages", () => {
  const graph = { nodes: [], edges: [
    { source:"<_:alice>",predicate:"urn:p",target:"<_:bob>" },
    { source:"<_:bob>",predicate:"urn:p",target:"<_:alice>" },
    { source:"<_:alice>",predicate:"urn:p",target:"urn:iri" },
  ] };
  const loaded = loadedLinksOf(graph, ["<_:alice>"]);
  assert.deepEqual(loaded.get("<_:alice>"), {outgoing:[["<urn:p>","<_:bob>"],["<urn:p>","<urn:iri>"]],incoming:[["<_:bob>","<urn:p>"]]});
  assert.match(expandQuery(["<_:alice>"],80,"default",false,loaded), /\(<urn:p> <_:bob>\)/);
  assert.deepEqual(statementTokens(graph.edges[0]), {subject:"<_:alice>",predicate:"<urn:p>",object:"<_:bob>"});
});

test("metadata batches decode blank result keys into the same canonical graph identity", async () => {
  const queries = [];
  const explorer = new RdfExplorer("urn:local",["en"],async q => {
    queries.push(q);
    return {results:{bindings:q.includes("COUNT(*)")
      ? [{selected:stored("alice"),links:{type:"literal",value:"3"}}]
      : [{selected:stored("alice"),source:stored("alice"),predicate:iri("urn:p"),target:iri("urn:iri")} ]}};
  });
  try {
    assert.equal((await explorer.expand(["<_:alice>","urn:iri"],80)).length,1);
    assert.equal((await explorer.linkCounts(["<_:alice>"])).get("<_:alice>"),3);
    assert.equal(queries.length,2);
    assert.ok(queries.every(q => q.includes("<_:alice>")));
  } finally { explorer.dispose(); }
});

test("connection discovery retains blank sources and targets without a source-target matrix", async () => {
  let requests=0;
  const row={source:stored("alice"),predicate:iri("urn:p"),target:stored("bob")};
  const result=await discoverConnections(["<_:alice>","<_:bob>","urn:iri"],async q=> {
    requests++;
    assert.match(q,/isBlank\(\?target\)/);
    return {results:{bindings:[row]}};
  },"default",new AbortController().signal);
  assert.deepEqual(result.bindings,[row]);
  assert.equal(requests,1);
});

test("classic handoff parses fixed references as typed blank nodes and preserves replay", () => {
  assert.deepEqual(parseNTriplesTerm("<_:a\\u0020b\\u005Cu0041>"),stored("a b\\u0041"));
  const entry={kind:"statement",subject:"<_:alice>",predicate:"<urn:p>",object:"<_:bob>"};
  assert.deepEqual(statementBinding(entry),{source:stored("alice"),predicate:iri("urn:p"),target:stored("bob")});
  assert.match(statementsQuery([entry]),/\(<_:alice> <urn:p> <_:bob>\)/);
});

test("response-only blank nodes are scoped per result while only trusted responses retain reference grants", () => {
  const raw=JSON.stringify({results:{bindings:[{source:stored("alice"),predicate:iri("urn:p"),target:{type:"bnode",value:"alice"}}]}});
  const imported=parseSparqlResponse(raw);
  const first=parseSparqlResponse(raw,{repositoryReferences:true});
  const second=parseSparqlResponse(raw,{repositoryReferences:true});
  assert.equal(sparqlFacetValueToken(sparqlNodeId(imported.results.bindings[0].source)),null);
  assert.equal(sparqlNodeId(first.results.bindings[0].source),"<_:alice>");
  assert.notEqual(sparqlNodeId(first.results.bindings[0].target),sparqlNodeId(second.results.bindings[0].target));
  assert.notEqual(sparqlNodeId(first.results.bindings[0].source),sparqlNodeId(first.results.bindings[0].target));
});

test("local workspace restoration retains certified IDs while arbitrary imported JSON cannot grant authority", () => {
  const raw=JSON.stringify({graph:{nodes:[{id:"<_:alice>",kind:"blank",label:"Alice",termValue:"alice"}],edges:[],revision:1},scope:"<_:graph>"});
  const imported=parseWorkspacePayload(raw);
  const restored=parseWorkspacePayload(raw,{repositoryReferences:true});
  assert.equal(sparqlFacetValueToken(imported.graph.nodes[0].id),null);
  assert.equal(restored.graph.nodes[0].id,"<_:alice>");
  assert.equal(restored.scope,"<_:graph>");
  const legacy=parseWorkspacePayload(JSON.stringify({graph:{nodes:[{id:"__rdf_bnode__:alice",kind:"blank",label:"Alice",termValue:"alice"}],edges:[],revision:1}}),{repositoryReferences:true});
  assert.equal(sparqlFacetValueToken(legacy.graph.nodes[0].id),null);
});

test("downgrading imported blank references preserves statements about statements and their identities",()=>{
  const edgeId=JSON.stringify(["<_:alice>","urn:p","<_:bob>"]);
  const graph={revision:1,nodes:[{id:"<_:alice>",label:"Alice",kind:"blank",termValue:"alice"},{id:"<_:bob>",label:"Bob",kind:"blank",termValue:"bob"}],
    edges:[{id:edgeId,source:"<_:alice>",predicate:"urn:p",label:"p",target:"<_:bob>"}],
    statementLinks:[{id:JSON.stringify(["<_:alice>","urn:ref","<_:alice>","urn:p","<_:bob>"]),source:"<_:alice>",predicate:"urn:ref",label:"ref",subject:"<_:alice>",statementPredicate:"urn:p",object:"<_:bob>",statementEdgeId:edgeId}]};
  const restored=parseWorkspacePayload(JSON.stringify({graph}));
  assert.equal(restored.graph.statementLinks.length,1);
  const link=restored.graph.statementLinks[0];
  assert.equal(link.source,restored.graph.nodes[0].id);
  assert.equal(link.subject,restored.graph.nodes[0].id);
  assert.equal(link.object,restored.graph.nodes[1].id);
  assert.equal(link.statementEdgeId,restored.graph.edges[0].id);
  assert.equal(restored.graph.edges[0].id,JSON.stringify([link.subject,link.statementPredicate,link.object]));
  const partial=parseWorkspacePayload(JSON.stringify({graph:{...graph,edges:[],nodes:graph.nodes.slice(0,1)}}));
  assert.equal(partial.graph.statementLinks.length,1);
  assert.equal(sparqlFacetValueToken(partial.graph.statementLinks[0].object),null,"a missing endpoint cannot regain authority when its statement is shown");
});

test("imported stored references do not collide with unverified labels that happen to have the same raw ID",()=>{
  const raw=JSON.stringify({graph:{nodes:[{id:"<_:alice>",kind:"blank",label:"Stored",termValue:"alice"},{id:"__rdf_bnode__:alice",kind:"blank",label:"Result",termValue:"alice"}],edges:[],revision:1}});
  const first=parseWorkspacePayload(raw);
  const second=parseWorkspacePayload(raw);
  assert.ok(first);
  assert.ok(second);
  assert.equal(new Set(first.graph.nodes.map(n=>n.id)).size,2);
  assert.notEqual(first.graph.nodes[0].id,second.graph.nodes[0].id);
  assert.ok(first.graph.nodes.every(node=>sparqlFacetValueToken(node.id)===null));
});

test("RDF export distinguishes result documents with equal blank labels and uses ordinary Turtle labels", () => {
  const first=sparqlNodeId({type:"bnode",value:"same","rdf4j:scope":"first"});
  const second=sparqlNodeId({type:"bnode",value:"same","rdf4j:scope":"second"});
  const turtle=graphTurtle({nodes:[],edges:[{source:first,predicate:"urn:p",target:second},{source:"<_:same>",predicate:"urn:p",target:first}],revision:1});
  assert.match(turtle,/_:b0/);
  assert.match(turtle,/_:b1/);
  assert.match(turtle,/_:b2/);
  assert.doesNotMatch(turtle,/<_:/);
});

test("selected blank values combine with literal facets in every repository graph scope", () => {
  const selection=new Map([["urn:knows",new Set(["<_:alice>"])],["urn:name",new Set([sparqlNodeId({type:"literal",value:"Name"})])]]);
  for (const scope of ["all","<_:graph>","urn:named"]) {
    const query=generatedFacetQuery(selection,{wikidata:false,scope});
    assert.match(query,/VALUES \?facetValue0 \{ <_:alice> \}/);
    assert.match(query,/VALUES \?facetValue1 \{ "Name" \}/);
    assert.doesNotMatch(query,/FILTER\(false\)/);
    assert.match(query,scope==="all" ? /GRAPH \?__facet/ : scope==="urn:named" ? /GRAPH <urn:named>/ : /GRAPH <_:graph>/);
  }
});

test("loaded types of blank resources populate metadata and the same type facet as IRIs",()=>{
  const graph={nodes:[{id:"<_:alice>",kind:"blank",label:"Alice"},{id:"urn:Person",kind:"iri",label:"Person"}],edges:[{source:"<_:alice>",predicate:"http://www.w3.org/1999/02/22-rdf-syntax-ns#type",target:"urn:Person"}],revision:1};
  const node=withLoadedTypes(graph).nodes[0];
  assert.deepEqual(node.types,[{id:"urn:Person",label:"Person"}]);
  assert.deepEqual(nodeTypeIds(node),["urn:Person"]);
});

test("fixed references follow the backend Unicode scalar rules without decoding twice",()=>{
  for(const token of ["<_:\\uD800>","<_:\\U0000DFFF>","<_:\\uD83D\\uDE00>","<_:\ud800>","<_:\udfff>"])
    assert.equal(sparqlTermFromNodeId(token),undefined,JSON.stringify(token));
  for(const raw of ["\ud800","\udfff","x\ud800y"])
    assert.throws(()=>sparqlNodeId(stored(raw)),/surrogate|Unicode/i);
  assert.deepEqual(sparqlTermFromNodeId("<_:\\U0001F600>"),stored("😀"));
  assert.deepEqual(sparqlTermFromNodeId("<_:😀>"),stored("😀"));
  assert.deepEqual(sparqlTermFromNodeId("<_:\\u005CuD800>"),stored("\\uD800"));
});

