test("result document identity initializes when secure-context randomUUID is unavailable",()=>{
  const url=new URL("../../../main/frontend/graph-explorer/rdf-results.ts",import.meta.url).href;
  const script=`Object.defineProperty(globalThis,"crypto",{value:{getRandomValues(array){array.fill(12);return array;}}}); const {parseSparqlResponse}=await import(${JSON.stringify(url)}); const response=parseSparqlResponse('{"results":{"bindings":[{"s":{"type":"bnode","value":"alice"}}]}}'); if(!response.results.bindings[0].s["rdf4j:scope"]) throw new Error("Missing document scope");`;
  const result=spawnSync(process.execPath,["--experimental-strip-types","--input-type=module","-e",script],{encoding:"utf8"});
  assert.equal(result.status,0,result.stderr);
});
